def seed_cases():
    with app.app_context():
        existing = LegalCase.query.count()
        print(f"\n=== LexGuard AI — Cases Seeder ===")
        print(f"Existing cases in DB: {existing}")

        if existing >= len(CASES):
            print(f"DB already has {existing} cases. Skipping seed.")
            return

        # Clear and re-seed for clean state
        print(f"Adding {len(CASES)} cases to DB...")
        LegalCase.query.delete()
        db.session.commit()

        for i, c in enumerate(CASES):
            case = LegalCase(**c)
            db.session.add(case)
            if (i + 1) % 50 == 0:
                db.session.flush()
                print(f"  {i+1} cases inserted...")

        db.session.commit()
        print(f"\n[OK] {len(CASES)} legal cases seeded successfully.\n")


if __name__ == "__main__":
    seed_cases()
